@layer components {
  /* Dialog: ui-sdk's stylesheet centers the box over the backdrop. The ViteHub dialog floats on a shadow, with no border. */
  [data-slot="dialog-content"] {
    border-width: 0;
    box-shadow: var(--vh-shadow-dialog);
  }

  /* The icon-only close button sits in the top end corner, as in shadcn. */
  [data-slot="dialog-content"] > [data-slot="dialog-close"][aria-label]:has(> svg:only-child) {
    background: transparent;
    border-color: transparent;
    color: var(--vh-muted);
    height: 1.75rem;
    inset-block-start: 0.75rem;
    inset-inline-end: 0.75rem;
    padding: 0;
    position: absolute;
    width: 1.75rem;
  }

  @media (hover: hover) {
    [data-slot="dialog-content"] > [data-slot="dialog-close"][aria-label]:has(> svg:only-child):hover {
      background: var(--vh-bg-muted);
      color: var(--vh-text);
    }
  }

  [data-slot="dialog-header"] {
    display: flex;
    flex-direction: column;
    gap: 0.375rem;
    padding-inline-end: 1.5rem;
  }

  [data-slot="dialog-header"] [data-slot="dialog-description"] {
    margin: 0;
  }

  [data-slot="dialog-footer"] {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    justify-content: flex-end;
  }
}

export { default as Dialog } from "./Dialog.vue";
export { default as DialogClose } from "./DialogClose.vue";
export { default as DialogContent } from "./DialogContent.vue";
export { default as DialogDescription } from "./DialogDescription.vue";
export { default as DialogFooter } from "./DialogFooter.vue";
export { default as DialogHeader } from "./DialogHeader.vue";
export { default as DialogTitle } from "./DialogTitle.vue";
export { default as DialogTrigger } from "./DialogTrigger.vue";
export type * from "./types.ts";

export interface DialogProps {
  open?: boolean;
  defaultOpen?: boolean;
}

export interface DialogEmits {
  "update:open": [open: boolean];
}

export interface DialogSlots {
  default?: () => unknown;
}

export interface DialogContentProps {
  closeLabel?: string;
}

export interface DialogContentSlots {
  default?: () => unknown;
  close?: () => unknown;
}

export interface DialogTriggerSlots {
  default?: () => unknown;
}

export interface DialogHeaderSlots {
  default?: () => unknown;
}

export interface DialogFooterSlots {
  default?: () => unknown;
}

export interface DialogTitleSlots {
  default?: () => unknown;
}

export interface DialogDescriptionSlots {
  default?: () => unknown;
}

export interface DialogCloseSlots {
  default?: () => unknown;
}
